window.docContents[253].resolve({"/Overview/#Cvc___lean----High-Level-API-for-CVC5--Overview--Check-sat-with-assumptions":{"contents":"Solver.checkSat actually has a fourth optional parameter assuming that accepts\nArray (Term Bool) values. It adds constraints to that check-sat without changing the\nsolver's actual assertions.\n\n#eval Env.runIO do\n  let (solver, b1, i1) ← setup\n  println! \"check-sat assuming {b1}\"\n  solver.checkSat (assuming := #[b1])\n    (ifSat := do\n      let b1 ← solver.getValue b1\n      let i1 ← solver.getValue i1\n      println! \"→ sat: b1 := {b1}, i1 := {i1}\")\n\n  let i1_eq_zero ← smt! i1 = 0\n  println! \"check-sat assuming {b1} and {i1_eq_zero}\"\n  solver.checkSat (assuming := #[b1, i1_eq_zero])\n    (ifSat := println! \"→ sat, unexpected!\")\n    (ifUnsat := println! \"→ unsat\")\n    (ifUnknown := fun explain =>\n      println! \"→ solver could not decide 😥:\\n  {explain}\")\n\n\ncheck-sat assuming b1\n→ sat: b1 := true, i1 := 1\ncheck-sat assuming b1 and (= i1 0)\n→ unsat\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Overview","header":"1.3. Check-sat with assumptions","id":"/Overview/#Cvc___lean----High-Level-API-for-CVC5--Overview--Check-sat-with-assumptions"}});